def simulate(capacity, accesses):
    from collections import OrderedDict
    if capacity<0: raise ValueError('capacity')
    cache=OrderedDict(); hits=0
    for key in accesses:
        if key in cache: hits+=1; cache.move_to_end(key)
        elif capacity:
            cache[key]=None
            if len(cache)>capacity: cache.popitem(last=False)
    return hits,list(cache)

